content = open('/Applications/stock_dashboard/frontend/src/App.jsx', 'r').read()
start = content.find('{/* \uc8fc\uac00 \ucc28\ud2b8 */')
end   = content.find('{/* \uc218\uae09 \ucc28\ud2b8 */', start)
print(f"range: {start}~{end}")

NC = (
    "          {/* candle chart */}\n"
    "          <div className=\"glass-panel\" style={{ padding:'1rem' }}>\n"
    "            <div style={{ display:'flex', alignItems:'center', gap:'1rem', marginBottom:'0.6rem', flexWrap:'wrap' }}>\n"
    "              <p style={{ fontSize:'0.8rem', color:'var(--text-secondary)' }}>\uc8fc\uac00 \ucc28\ud2b8 ({chartDays===365?'1\ub144':chartDays+'\uc77c'})</p>\n"
    "              {chartData.length > 0 && (\n"
    "                <div style={{ display:'flex', gap:'0.8rem', fontSize:'0.68rem' }}>\n"
    "                  {[['MA5','#facc15'],['MA20','#f97316'],['MA60','#a78bfa']].map(([lb,cl]) => (\n"
    "                    <span key={lb} style={{ display:'flex', alignItems:'center', gap:'0.25rem' }}>\n"
    "                      <span style={{ display:'inline-block', width:'16px', height:'2px', background:cl }}/><span style={{ color:'var(--text-secondary)' }}>{lb}</span>\n"
    "                    </span>\n"
    "                  ))}\n"
    "                  {[['\uc591\ubd09','#ef4444'],['\uc74c\ubd09','#3b82f6']].map(([lb,cl]) => (\n"
    "                    <span key={lb} style={{ display:'flex', alignItems:'center', gap:'0.3rem' }}>\n"
    "                      <span style={{ display:'inline-block', width:'8px', height:'10px', background:cl, borderRadius:'1px' }}/><span style={{ color:'var(--text-secondary)' }}>{lb}</span>\n"
    "                    </span>\n"
    "                  ))}\n"
    "                </div>\n"
    "              )}\n"
    "            </div>\n"
    "            {chartData.length === 0 ? (\n"
    "              <div style={{ display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', height:'260px', gap:'0.6rem' }}>\n"
    "                {collecting ? <><div style={{width:'22px',height:'22px',borderRadius:'50%',border:'2px solid var(--accent-mint)',borderTopColor:'transparent',animation:'spin 0.8s linear infinite'}}/><span style={{color:'var(--accent-mint)',fontSize:'0.8rem'}}>\uc8fc\uac00 \uc218\uc9d1 \uc911...</span></> : <span style={{color:'var(--text-secondary)',fontSize:'0.8rem'}}>\uc8fc\uac00 \ub370\uc774\ud130 \uc5c6\uc74c</span>}\n"
    "              </div>\n"
    "            ) : (() => {\n"
    "              const mc=(arr,n)=>arr.map((_,i)=>{if(i<n-1)return null;return arr.slice(i-n+1,i+1).reduce((s,d)=>s+(d.close||0),0)/n;});\n"
    "              const ma5=mc(chartData,5),ma20=mc(chartData,20),ma60=mc(chartData,60);\n"
    "              const W=900,HC=220,HV=55,PL=58,PR=8,PT=10,PB=20,N=chartData.length;\n"
    "              const minP=Math.min(...chartData.map(d=>d.low||d.close||0))*0.998;\n"
    "              const maxP=Math.max(...chartData.map(d=>d.high||d.close||0))*1.002;\n"
    "              const maxV=Math.max(...chartData.map(d=>d.volume||0))||1;\n"
    "              const xs=(W-PL-PR)/N, xp=i=>PL+(i+0.5)*xs;\n"
    "              const yp=v=>PT+(1-(v-minP)/(maxP-minP))*(HC-PT-PB);\n"
    "              const yv=v=>HV-2-(v/maxV)*(HV-4);\n"
    "              const pt=Array.from({length:4},(_,i)=>minP+(maxP-minP)*i/3);\n"
    "              const fp=v=>v>=100000?(v/10000).toFixed(0)+\"\ub9cc\":Math.round(v).toLocaleString(\"ko-KR\");\n"
    "              const xt=Array.from({length:5},(_,i)=>Math.floor(i*(N-1)/4));\n"
    "              const [tip,setTip]=React.useState(null);\n"
    "              const cw=Math.max(1,xs*0.6);\n"
    "              return (\n"
    "                <div style={{position:\"relative\"}}>\n"
    "                  <svg viewBox={`0 0 ${W} ${HC+HV+8}`} style={{width:\"100%\",height:\"auto\",cursor:\"crosshair\"}} onMouseLeave={()=>setTip(null)}>\n"
    "                    {pt.map((v,i)=>(<g key={i}><line x1={PL} x2={W-PR} y1={yp(v)} y2={yp(v)} stroke=\"rgba(255,255,255,0.05)\" strokeWidth=\"1\"/><text x={PL-4} y={yp(v)+4} textAnchor=\"end\" fontSize=\"9\" fill=\"rgba(100,116,139,0.8)\">{fp(v)}</text></g>))}\n"
    "                    <line x1={PL} x2={W-PR} y1={HC-PB} y2={HC-PB} stroke=\"rgba(255,255,255,0.08)\" strokeWidth=\"1\"/>\n"
    "                    <line x1={PL} x2={W-PR} y1={HC+2} y2={HC+2} stroke=\"rgba(255,255,255,0.06)\" strokeWidth=\"1\"/>\n"
    "                    {xt.map(i=>(<text key={i} x={xp(i)} y={HC-2} textAnchor=\"middle\" fontSize=\"9\" fill=\"rgba(100,116,139,0.8)\">{chartData[i]?.date?.slice(5).replace(\"-\",\"/\")}</text>))}\n"
    "                    {chartData.map((d,i)=>{const u=(d.close||0)>=(d.open||d.close||0);const vh=HV-2-yv(d.volume||0);return <rect key={i} x={xp(i)-cw/2} y={HC+2+yv(d.volume||0)} width={cw} height={Math.max(1,vh)} fill={u?\"rgba(239,68,68,0.35)\":\"rgba(59,130,246,0.35)\"}/>;})}\n"
    "                    {chartData.map((d,i)=>{const o=d.open||d.close||0,h=d.high||d.close||0,l=d.low||d.close||0,c=d.close||0,u=c>=o,cl=u?\"#ef4444\":\"#3b82f6\",bT=yp(Math.max(o,c)),bH=Math.max(1,Math.abs(yp(o)-yp(c))),cx=xp(i);return(<g key={i} onMouseEnter={()=>setTip({i,x:cx,d,ma5:ma5[i],ma20:ma20[i],ma60:ma60[i]})}><line x1={cx} x2={cx} y1={yp(h)} y2={bT} stroke={cl} strokeWidth=\"1\"/><rect x={cx-cw/2} y={bT} width={cw} height={bH} fill={u?cl:\"none\"} stroke={cl} strokeWidth=\"1\"/><line x1={cx} x2={cx} y1={bT+bH} y2={yp(l)} stroke={cl} strokeWidth=\"1\"/></g>);})}\n"
    "                    {(()=>{let p=\"\";chartData.forEach((d,i)=>{if(d.close!=null)p+=i===0?`M${xp(i)},${yp(d.close)}`:`L${xp(i)},${yp(d.close)}`;});return <path d={p} fill=\"none\" stroke=\"var(--accent-mint)\" strokeWidth=\"1.5\" opacity=\"0.7\"/>;})()}\n"
    "                    {[{ma:ma5,cl:\"#facc15\",w:1.2,da:\"4 3\"},{ma:ma20,cl:\"#f97316\",w:1.5,da:\"5 3\"},{ma:ma60,cl:\"#a78bfa\",w:1.5,da:\"6 3\"}].map(({ma,cl,w,da},li)=>{let p=\"\";ma.forEach((v,i)=>{if(v!=null)p+=ma[i-1]!=null?` L${xp(i)},${yp(v)}`:`M${xp(i)},${yp(v)}`;});return <path key={li} d={p} fill=\"none\" stroke={cl} strokeWidth={w} strokeDasharray={da}/>;}) }\n"
    "                    {tip&&<line x1={tip.x} x2={tip.x} y1={PT} y2={HC-PB} stroke=\"rgba(255,255,255,0.2)\" strokeWidth=\"1\" strokeDasharray=\"4 2\"/>}\n"
    "                  </svg>\n"
    "                  {tip&&(()=>{const d=tip.d,u=(d.close||0)>=(d.open||d.close||0),chg=d.open?((d.close-d.open)/d.open*100):0;return(<div style={{position:\"absolute\",top:8,left:tip.x>W*0.6?\"5%\":\"55%\",background:\"rgba(10,10,20,0.97)\",border:\"1px solid rgba(255,255,255,0.12)\",borderRadius:\"8px\",padding:\"0.6rem 0.8rem\",fontSize:\"0.72rem\",lineHeight:1.8,minWidth:\"140px\",pointerEvents:\"none\"}}><div style={{fontWeight:700,color:\"var(--text-primary)\",marginBottom:\"0.2rem\"}}>{d.date}</div>{[[\"\\uc2dc\\uac00\",d.open],[\"\\uace0\\uac00\",d.high],[\"\\uc800\\uac00\",d.low],[\"\\uc885\\uac00\",d.close]].map(([lb,v])=>(<div key={lb} style={{display:\"flex\",justifyContent:\"space-between\",gap:\"1rem\"}}><span style={{color:\"var(--text-secondary)\"}}>{lb}</span><span style={{color:u?\"#ef4444\":\"#3b82f6\",fontWeight:600}}>{Math.round(v||0).toLocaleString(\"ko-KR\")}</span></div>))}<div style={{display:\"flex\",justifyContent:\"space-between\",gap:\"1rem\"}}><span style={{color:\"var(--text-secondary)\"}}>{\"\\ub4f1\\ub77d\"}</span><span style={{color:u?\"#ef4444\":\"#3b82f6\",fontWeight:600}}>{chg>=0?\"+\":\"\"}{chg.toFixed(2)}%</span></div><div style={{display:\"flex\",justifyContent:\"space-between\",gap:\"1rem\"}}><span style={{color:\"var(--text-secondary)\"}}>{\"\\uac70\\ub798\\ub7c9\"}</span><span style={{color:\"rgba(255,255,255,0.8)\"}}>{Math.round(d.volume||0).toLocaleString(\"ko-KR\")}</span></div><div style={{borderTop:\"1px solid rgba(255,255,255,0.08)\",marginTop:\"0.3rem\",paddingTop:\"0.3rem\"}}>{[[\"MA5\",tip.ma5,\"#facc15\"],[\"MA20\",tip.ma20,\"#f97316\"],[\"MA60\",tip.ma60,\"#a78bfa\"]].map(([lb,v,cl])=>v!=null&&(<div key={lb} style={{display:\"flex\",justifyContent:\"space-between\",gap:\"1rem\"}}><span style={{color:cl}}>{lb}</span><span style={{color:cl}}>{Math.round(v).toLocaleString(\"ko-KR\")}</span></div>))}</div></div>);})()}\n"
    "                </div>\n"
    "              );\n"
    "            })()}\n"
    "          </div>\n\n"
    "          "
)

content = content[:start] + NC + content[end:]
open('/Applications/stock_dashboard/frontend/src/App.jsx', 'w').write(content)
print("OK bT:", 'bT=' in content, "MA:", 'strokeDasharray' in content)
